properties.query:
let queryFrequency = ago(1d);
let queryPeriod = ago(13d);
let thresholdMultiplier = 1.3;
let safeline = datatable(SearchKey: string)[];
let WatchlistThreshold = toscalar(union isfuzzy=true safeline, _GetWatchlist("UsageThreshold") | distinct SearchKey);
let UsageCache = materialize(
    Usage
    // Set lookback to be startofday to ensure data captured represent days of the week, rather than 24 hour windows
    // based on the time of the query running
    | where TimeGenerated >= startofday(queryPeriod)
    | where IsBillable == true
    | extend Workspace = tostring(split(ResourceUri, "/")[-1])
    );
let CalculatedThreshold = toscalar(UsageCache
    | where TimeGenerated < startofday(queryFrequency) //Exclude yesterday (timeframe being analysed)
    | where dayofweek(TimeGenerated) between (1d .. 5d) //Exclude weekends
    | summarize TotalGB = sum(Quantity) by bin(TimeGenerated, 1d), Workspace
    | summarize GBPerDay = avg(TotalGB) / 1000
    | extend newThreshold = round(GBPerDay * thresholdMultiplier, 2)
    | project newThreshold);
UsageCache
// Look back over the most recent full day's data usage
| where TimeGenerated between (startofday(queryFrequency)..startofday(now()))
| summarize GBytes = sum(Quantity) / 1000 by Workspace
| where toreal(GBytes) > max_of(toreal(WatchlistThreshold), CalculatedThreshold)
| project
    Workspace,
    GBytes = strcat(round(GBytes, 2), "GB"),
    WatchlistThreshold,
    CalculatedThreshold
